<?php
defined( 'ABSPATH' ) || exit;

add_action( 'rest_api_init', function () { register_rest_route( 'brounhall/v1', '/blogs', array( 'methods' => WP_REST_Server::READABLE, 'callback' => 'brounhall_rest_blogs', 'permission_callback' => '__return_true' ) ); register_rest_route( 'brounhall/v1', '/blogs/(?P<slug>[^/]+)', array( 'methods' => WP_REST_Server::READABLE, 'callback' => 'brounhall_rest_blog', 'permission_callback' => '__return_true' ) ); } );
function brounhall_blog_data( $post ) { $data = brounhall_normalize_blog_data( json_decode( get_post_meta( $post->ID, '_brounhall_blog_data', true ), true ) ); $data['id'] = (int) $post->ID; $data['slug'] = $post->post_name; $data['title'] = get_the_title( $post ); $data['image'] = array( 'imageId' => (int) $data['imageId'], 'alt' => $data['imageAlt'] ); $media = brounhall_media_response( (int) $data['imageId'], $data['imageAlt'] ); if ( $media ) { $data['image'] = array_merge( $data['image'], $media ); } unset( $data['imageId'], $data['imageAlt'] ); return $data; }
function brounhall_blog_query() { return new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => 50, 'orderby' => array( 'menu_order' => 'ASC', 'date' => 'DESC' ), 'no_found_rows' => true, 'meta_key' => '_brounhall_is_blog', 'meta_value' => '1' ) ); }
function brounhall_rest_blogs() { $items = array(); foreach ( brounhall_blog_query()->posts as $post ) { $data = brounhall_blog_data( $post ); $items[] = array( 'id' => $data['id'], 'slug' => $data['slug'], 'title' => $data['title'], 'excerpt' => $data['excerpt'], 'category' => $data['category'], 'author' => $data['author'], 'image' => $data['image'] ); } return rest_ensure_response( array( 'items' => $items ) ); }
function brounhall_rest_blog( WP_REST_Request $request ) { $slug = (string) $request['slug']; if ( ! brounhall_blog_slug_is_valid( $slug ) ) { return new WP_Error( 'brounhall_invalid_blog_slug', 'Invalid blog slug', array( 'status' => 400 ) ); } $post = get_page_by_path( $slug, OBJECT, 'post' ); if ( ! $post || 'publish' !== $post->post_status || '1' !== get_post_meta( $post->ID, '_brounhall_is_blog', true ) ) { return new WP_Error( 'brounhall_blog_not_found', 'Blog not found', array( 'status' => 404 ) ); } return rest_ensure_response( brounhall_blog_data( $post ) ); }
